def card(task, wd):
    specs = [{'id': 'pie7', 'type': 'pie', 'slices': 7, 'medium': 'video'}, {'id': 'bar3d', 'type': 'bar', '3d': True}, {'id': 'dual', 'type': 'line', 'dual_axis': True}, {'id': 'stack9', 'type': 'stacked_bar', 'segments': 9}, {'id': 'animpie', 'type': 'pie', 'slices': 3, 'animated': True, 'medium': 'video'}, {'id': 'dash6', 'type': 'dashboard', 'panels': 6}, {'id': 'trunc', 'type': 'bar', 'baseline': 40}, {'id': 'ok_bar', 'type': 'bar', 'baseline': 0}, {'id': 'ok_pie', 'type': 'pie', 'slices': 3, 'medium': 'video'}]
    expected = {'pie7': False, 'bar3d': False, 'dual': False, 'stack9': False, 'animpie': False, 'dash6': False, 'trunc': False, 'ok_bar': True, 'ok_pie': True}
    verdicts = {s['id']: [r for r, f, _ in _BLACKLIST_RULES if f(s)] for s in specs}
    checks = [check('lint %s' % k, (not v) == expected[k], v, 'accept' if expected[k] else 'reject') for k, v in verdicts.items()]
    shares = [31, 22, 17, 12, 9, 6, 3]

    def bars(baseline, path):
        a = canvas(300, 220, '#ffffff')
        for i, v in enumerate(sorted(shares, reverse=True)):
            h = (v - baseline) * 6
            rect(a, 20 + i * 38, 200 - h, 20 + i * 38 + 28, 200, '#4a6fa5')
        return save_png(a, path)
    good = bars(0, wd / 'pie7_as_bars.png')
    trunc = bars(2, wd / 'truncated_baseline.png')
    xs = [20 + i * 38 + 14 for i in range(7)]
    hg = bar_heights(load_png(good), 200, xs, '#ffffff')
    ht = bar_heights(load_png(trunc), 200, xs, '#ffffff')
    srt = sorted(shares, reverse=True)
    checks.append(check('rebuilt bars proportional from a zero baseline', max_ratio_err(hg, srt) < 0.01, max_ratio_err(hg, srt), '< 0.01'))
    checks.append(check('negative control: a truncated baseline distorts the ratios', max_ratio_err(ht, srt) > 0.1, max_ratio_err(ht, srt), '> 0.1'))
    return (checks, [good, wjson(wd / 'lint.json', verdicts)])

def card(task, wd):
    np = _np()
    W, H, fps, NH = (270, 480, 30, 25)
    stats = [40, 75]
    BW = 200

    def value(t):
        if t < 1.2:
            return stats[0] * ease('easeOutCubic', t / 1.2)
        if t < 2.0:
            return stats[0]
        return stats[0] + (stats[1] - stats[0]) * ease('easeOutCubic', (t - 2.0) / 1.2)

    def frame(v):
        a = canvas(W, H, '#10233a')
        n = int(round(v))
        draw_seg(a, fmt_int(n, 'ddd'), 'ddd', NH, 100, 180, '#ffffff')
        rect(a, 35, 260, 35 + round(n / 100 * BW), 280, '#5bd1a5')
        return a
    T = 3.6
    vid = write_video(wd / 'stat_morph.mp4', [frame(value(k / fps)) for k in range(int(T * fps))], fps)
    cut = write_video(wd / 'stat_hard_cut.mp4', [frame(stats[0] * ease('easeOutCubic', min(1, k / fps / 1.2)) if k / fps < 2.0 else stats[1]) for k in range(int(T * fps))], fps)

    def measure(path):
        fr = read_video(path)
        nums = [seg_value(read_seg(f, 'ddd', NH, 100, 180, '#10233a', fg='#ffffff')) for f in fr]
        widths = [int(near(f[270], '#5bd1a5', 8).sum()) for f in fr]
        return (nums, widths)
    nums, widths = measure(vid)
    cn, cw = measure(cut)
    pair = max((abs(w - round(n / 100 * BW)) for n, w in zip(nums, widths) if n is not None))
    jump = max((abs(b - a) for a, b in zip(widths, widths[1:])))
    cjump = max((abs(b - a) for a, b in zip(cw, cw[1:])))
    checks = [check('counts from 0', nums[0] == 0, nums[0], 0), check('first stat lands at 40', nums[int(1.5 * fps)] == 40, nums[int(1.5 * fps)], 40), check('second stat lands at 75', nums[-1] == 75, nums[-1], 75), check('bar width bound to the number in every frame (px)', pair <= 1, pair, '<= 1'), check('morph is continuous (max px per frame)', jump <= 10, jump, '<= 10'), check('hero numeral 80-120 px at 1080p', 80 <= NH * 4 <= 120, NH * 4, '80..120'), check('negative control: a hard cut jumps the shape', cjump > 10, cjump, '> 10')]
    return (checks, [vid])

def card(task, wd):
    cases = {1234: '1.2K', 3400000: '3.4M', 5600000000: '5.6B', 999: '999', 12345: '12.3K', -2500000: '-2.5M'}
    got = {k: compact(k) for k in cases}
    ar = compact(3400000, ar=True)
    nums = node_eval("console.log(JSON.stringify([new Intl.NumberFormat('ar-EG',{maximumFractionDigits:1}).format(3.4),new Intl.NumberFormat('ar-u-nu-latn',{maximumFractionDigits:1}).format(3.4),new Intl.NumberFormat('en-US',{style:'percent',maximumFractionDigits:1}).format(0.1234)]))")
    write_json(wd / 'formats.json', {'compact': got, 'arabic': ar, 'intl': nums})
    return ([check('thresholds 1e3/1e6/1e9 with one decimal', got == cases, got, cases), check('Arabic words ألف/مليون/مليار', ar == '3.4 مليون', ar, '3.4 مليون'), check('ar-EG -> ٣٫٤ and ar-u-nu-latn keeps 3.4', nums[0] == '٣٫٤' and nums[1] in ('3.4', '3٫4'), nums[:2], ['٣٫٤', '3.4']), check('percent with 1 decimal', nums[2] == '12.3%', nums[2], '12.3%'), check('negative control: raw str() is not compact', not str(1234) == cases[1234], str(1234), '1.2K')], [wd / 'formats.json'])

def card(task, wd):
    np = _np()
    res = {}
    for name, pal in (('light', PAL8_LIGHT), ('dark', PAL8_DARK)):
        c = [rgb(x) for x in pal]
        res[name] = {'normal': min((de2000(a, b) for a, b in zip(c, c[1:])))}
        for k in ('protan', 'deutan', 'tritan'):
            s = [simulate_cvd(x, k) for x in c]
            res[name][k] = min((de2000(a, b) for a, b in zip(s, s[1:])))
    worst = {n: min((v[k] for k in ('protan', 'deutan', 'tritan'))) for n, v in res.items()}
    ids = ['north', 'south', 'east', 'west']
    colour_of = {sid: PAL8_LIGHT[i] for i, sid in enumerate(ids)}
    vals1 = {'north': 5, 'south': 9, 'east': 2, 'west': 7}
    vals2 = {'north': 9, 'south': 1, 'east': 8, 'west': 3}
    by_rank = lambda v: {sid: PAL8_LIGHT[r] for r, sid in enumerate(sorted(v, key=lambda s: -v[s]))}
    W, H = (8 * 30, 60)
    a = canvas(W, H, '#ffffff')
    for i, cc in enumerate(PAL8_LIGHT):
        rect(a, i * 30, 0, i * 30 + 28, 28, cc)
    for i, cc in enumerate(PAL8_DARK):
        rect(a, i * 30, 30, i * 30 + 28, 58, cc)
    png = save_png(a, wd / 'palettes.png')
    b = load_png(png)
    sampled = ['#%02x%02x%02x' % tuple((int(v) for v in b[14, i * 30 + 14])) for i in range(8)]
    bad = [rgb('#d62728'), rgb('#2ca02c')]
    bad_de = de2000(simulate_cvd(bad[0], 'deutan'), simulate_cvd(bad[1], 'deutan'))
    risk = ['#cfe8d6', '#f3e2a6', '#f1b98a', '#e98a86']
    risk_dark = ['#1f5a3b', '#6b5a17', '#7a4219', '#7f2626']
    util = lambda u: '#ff907a' if u >= 1 else '#ffe083' if u >= 0.72 else '#b4ed88' if u >= 0.35 else '#8cffc0'
    out = wjson(wd / 'palette_report.json', {'adjacent_dE2000': res, 'documented': {'light': 9.1, 'dark': 8.4}, 'note': 'documented 9.1 / 8.4 not reproduced exactly; measured worst adjacent under CVD simulation reported'})
    checks = [check('8 unique slots per palette', len(set(PAL8_LIGHT)) == 8 and len(set(PAL8_DARK)) == 8, 8, 8), check('rendered swatches carry the slot colours in identity order', sampled == PAL8_LIGHT, sampled[:3], PAL8_LIGHT[:3]), check('light: worst adjacent dE2000 under CVD >= 8', worst['light'] >= 8, worst['light'], '>= 8'), check('dark: worst adjacent dE2000 under CVD >= 8', worst['dark'] >= 8, worst['dark'], '>= 8'), check('colour follows the series id, not its rank', colour_of == {s: colour_of[s] for s in ids} and by_rank(vals1) != by_rank(vals2), colour_of, 'stable across periods'), check('risk ramps run green -> red (R - G rises, light and dark)', all((rgb(y)[0] - rgb(y)[1] > rgb(x)[0] - rgb(x)[1] for P in (risk, risk_dark) for x, y in zip(P, P[1:]))), [rgb(x)[0] - rgb(x)[1] for x in risk], 'increasing'), check('utilisation ramp thresholds .35/.72/1.0', [util(u) for u in (0.2, 0.5, 0.8, 1.2)] == ['#8cffc0', '#b4ed88', '#ffe083', '#ff907a'], True, True), check('negative control: a red/green pair fails the CVD threshold', bad_de < 8, bad_de, '< 8')]
    return (checks, [png, out])
